package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

type Product struct {
	ID    int    `json:"id"`
	Name  string `json:"name"`
	Price float64 `json:"price"`
	Category string `json:"category"`
}

// searchProducts handles product search with filtering
func searchProducts(w http.ResponseWriter, r *http.Request) {
	category := r.URL.Query().Get("category")
	sortBy := r.URL.Query().Get("sort")
	minPrice := r.URL.Query().Get("min_price")

	// Build base query
	query := "SELECT id, name, price, category FROM products WHERE 1=1"

	if category != "" {
		// Parameterized - safe
		query += " AND category = $1"
	}

	if minPrice != "" {
		// Parameterized - safe
		query += " AND price >= $2"
	}

	// Sort ordering - validated against allowlist... or so it seems
	if sortBy != "" {
		allowedSorts := []string{"name", "price", "category"}
		sortValid := false
		for _, allowed := range allowedSorts {
			if strings.EqualFold(sortBy, allowed) {
				sortValid = true
				break
			}
		}
		if sortValid {
			query += " ORDER BY " + sortBy
		}
	}

	// Direction parameter - THIS is the vulnerable part
	direction := r.URL.Query().Get("dir")
	if direction != "" {
		// Developer assumed only "ASC" or "DESC" would be passed
		// but no validation is performed
		query += " " + direction
	}

	var rows *sql.Rows
	var err error

	switch {
	case category != "" && minPrice != "":
		rows, err = db.Query(query, category, minPrice)
	case category != "":
		rows, err = db.Query(query, category)
	case minPrice != "":
		rows, err = db.Query(query, minPrice)
	default:
		rows, err = db.Query(query)
	}

	if err != nil {
		http.Error(w, "Internal error", 500)
		log.Printf("Query error: %v", err)
		return
	}
	defer rows.Close()

	var products []Product
	for rows.Next() {
		var p Product
		if err := rows.Scan(&p.ID, &p.Name, &p.Price, &p.Category); err != nil {
			continue
		}
		products = append(products, p)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(products)
}

// healthCheck endpoint for LB probes
func healthCheck(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	fmt.Fprint(w, "ok")
}

func main() {
	http.HandleFunc("/api/products/search", searchProducts)
	http.HandleFunc("/health", healthCheck)
	log.Fatal(http.ListenAndServe(":8080", nil))
}
